# Builds dist\Axion.exe (Windows amd64) and the release package, on Windows.
# Same steps as build.sh (which needs bash and python3).
#
#   .\build\build.ps1 [-Version 0.9.1] [-SkipTests] [-NoPackage]
#
# The icon, manifest and version resource (cmd\axion\rsrc_windows_amd64.syso)
# is generated by cmd\axion-rsrc from build\axion-mark.png and
# build\axion.manifest, with the version given here (no llvm-windres needed).
param(
  [string]$Version = '0.9.1',
  [switch]$SkipTests,
  [switch]$NoPackage
)
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Set-Location $root

$goDir = 'C:\Program Files\Go\bin'
if (Test-Path $goDir) { $env:Path = "$goDir;$env:Path" }
$env:GOFLAGS = '-mod=mod'; $env:GOPROXY = 'off'; $env:GOSUMDB = 'off'; $env:CGO_ENABLED = '0'
$env:GOOS = 'windows'; $env:GOARCH = 'amd64'

if ($Version -notmatch '^(\d+)\.(\d+)\.(\d+)$') { throw "versão inválida: $Version (use maior.menor.correção)" }

# --- resources (icon, manifest, version) ------------------------------------
go run ./cmd/axion-rsrc -version $Version
if ($LASTEXITCODE) { throw 'axion-rsrc falhou' }

# --- checks and build -------------------------------------------------------
go vet ./cmd/... ./internal/...
if ($LASTEXITCODE) { throw 'go vet falhou' }
if (-not $SkipTests) {
  # cmd\axion is not tested here: its test binary inherits the administrator manifest.
  go test ./internal/...
  if ($LASTEXITCODE) { throw 'testes falharam' }
}
New-Item -ItemType Directory -Force dist | Out-Null
go build -trimpath -ldflags "-s -w -H windowsgui -X main.Version=$Version" -o dist\Axion.exe ./cmd/axion
if ($LASTEXITCODE) { throw 'go build falhou' }
Get-Item dist\Axion.exe | ForEach-Object { "{0}  {1:N0} bytes" -f $_.Name, $_.Length }
if ($NoPackage) { return }

# --- package ----------------------------------------------------------------
$utf8 = New-Object Text.UTF8Encoding($false)
$name = "Axion-$Version-win64"
$pkg = Join-Path $root "dist\$name"
if (Test-Path $pkg) { Remove-Item $pkg -Recurse -Force }
New-Item -ItemType Directory -Force $pkg | Out-Null
Copy-Item dist\Axion.exe $pkg

function Assert-Pinned([string]$file, [string]$source) {
  $h = (Get-FileHash $file -Algorithm SHA256).Hash.ToLower()
  if (-not (Select-String -Path $source -Pattern $h -SimpleMatch -Quiet)) { throw "hash de $(Split-Path $file -Leaf) não confere com o código ($source)" }
}
$wv2 = Join-Path $root 'third_party\go-webview2\webviewloader\sdk\x64\WebView2Loader.dll'
Assert-Pinned $wv2 (Join-Path $root 'cmd\axion\main_windows.go')
Copy-Item $wv2 $pkg
$pm = Join-Path $root 'third_party\presentmon\PresentMon-2.6.0-x64.exe'
Assert-Pinned $pm (Join-Path $root 'internal\app\perf.go')
Copy-Item $pm $pkg

function Write-Crlf([string]$text, [string]$dest) {
  $t = $text -replace "`r`n", "`n" -replace "`n", "`r`n"
  [IO.File]::WriteAllText($dest, $t, $utf8)
}
Write-Crlf ((Get-Content (Join-Path $root 'build\LEIA-ME.txt') -Raw -Encoding UTF8) -replace '@VERSION@', $Version) (Join-Path $pkg 'LEIA-ME.txt')
Write-Crlf (Get-Content (Join-Path $root 'build\THIRD-PARTY-NOTICES.txt') -Raw -Encoding UTF8) (Join-Path $pkg 'THIRD-PARTY-NOTICES.txt')
Write-Crlf (Get-Content (Join-Path $root 'LICENSE') -Raw -Encoding UTF8) (Join-Path $pkg 'LICENSE.txt')
# The tool writes the file itself: captured output would be decoded with the
# console code page and lose the accents.
go run ./cmd/axion-matrix -o (Join-Path $pkg 'MATRIZ-DE-EVIDENCIAS.md')
if ($LASTEXITCODE) { throw 'axion-matrix falhou' }

$sums = foreach ($f in 'Axion.exe', 'WebView2Loader.dll', 'PresentMon-2.6.0-x64.exe') { '{0}  {1}' -f (Get-FileHash (Join-Path $pkg $f) -Algorithm SHA256).Hash.ToLower(), $f }
[IO.File]::WriteAllText((Join-Path $pkg 'SHA256SUMS.txt'), (($sums -join "`n") + "`n"), $utf8)

$zip = Join-Path $root "dist\$name.zip"
if (Test-Path $zip) { Remove-Item $zip -Force }
Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem
$za = [IO.Compression.ZipFile]::Open($zip, 'Create')
try {
  foreach ($f in Get-ChildItem $pkg -File | Sort-Object Name) {
    [void][IO.Compression.ZipFileExtensions]::CreateEntryFromFile($za, $f.FullName, "$name/$($f.Name)", 'Optimal')
  }
} finally { $za.Dispose() }
Get-ChildItem $pkg | Select-Object Name, Length | Format-Table -AutoSize
Get-Item $zip | ForEach-Object { "{0}  {1:N0} bytes" -f $_.Name, $_.Length }
$sums
